                    b = build_domain(case, n, partial, params, 0)
                    state = (1, (partial,), F(6), 0, -1)
                    assert encode(state, a, n) == encode(state, b, n)
                    assert domain_verdict(a, 2)[0] and not domain_verdict(b, 2)[0]
